	unlock = {
		{ type = "interact" },
		{ type = "target" },
	},
	hint = [=[Seek the Forsaken ranger who keeps a farm of skulls and hounds in the south-west.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Nathanos Blightcaller is the champion of the {link:forsaken}Forsaken{/link} in the {link:eastern-plaguelands}Eastern Plaguelands{/link}. In life he was Nathanos Marris, a ranger lord of {link:lordaeron}Lordaeron{/link}, and the only human ever allowed to train among the rangers of {link:quel-thalas}Quel'Thalas{/link}. He fell to the {link:scourge}Scourge{/link} on his own farm and rose as its slave. {link:sylvanas-windrunner}Sylvanas Windrunner{/link} set him free. Now he keeps the {link:the-marris-stead}Marris Stead{/link} with his blighthounds, and he hunts the Scourge and the living with the same cold hatred. He is cruel to those who serve him, and he trusts no one but the Dark Lady.]=],
		},
		{
			title = "Significance",
			text = [=[Nathanos is two things at once, and both sides of the war know it. To the {link:alliance}Alliance{/link} he was a hero. His skill won victories over a decade of war, and no other human ever rose to the rank of ranger lord. To the {link:forsaken}Forsaken{/link} he is the first and most feared of {link:sylvanas-windrunner}the Banshee Queen{/link}'s champions. His fate is a wound for the Alliance. The regent in {link:stormwind-city}Stormwind{/link} learned of it and sent an army to end him.]=],
		},
		{
			title = "Life and Death",
			text = [=[Nathanos was born human in {link:lordaeron}Lordaeron{/link}. The high elves took him into their ranger order, which they had never done for any other of his race, and he rose to its highest rank. When the {link:scourge}Scourge{/link} swept over the eastern marches, he stood his ground on his farm in defense of the kingdom. A great wave of the dead overwhelmed him. The last thing he saw was an abomination hovering over him, its entrails hanging from its chest. He woke as one of the Scourge, his mind bound to the Lich King's. He was helpless for a long time. Then {link:sylvanas-windrunner}the Banshee Queen{/link} came for him, as he had somehow known she would, and broke his chains.]=],
		},
		{
			title = "Deeds",
			text = [=[• He hunted the abomination Ramstein across the wastes for months after his freedom, until it fled into Stratholme.
• He trains the {link:forsaken}Forsaken{/link} whom {link:sylvanas-windrunner}the Dark Lady{/link} sends him, with contempt and with no mercy.
• He slew the agents of {link:si-7}SI:7{/link} whom {link:stormwind-city}Stormwind{/link} sent to learn who the Blightcaller was.
• He plots against the {link:scarlet-crusade}Scarlet Crusade{/link} on the orders of {link:varimathras}Varimathras{/link}.]=],
		},
		{
			title = "The Present Day",
			text = [=[Nathanos keeps the {link:the-marris-stead}Marris Stead{/link} alone with his hounds. He sends his servants to feed the hounds with rot from {link:corin-s-crossing}Corin's Crossing{/link}, to clear the plaguebats from his sky, and to hunt the monsters of the north. The {link:forsaken}Forsaken{/link} who survive his training earn a place among his champions. The soldiers of the {link:alliance}Alliance{/link} who come to the stead do not usually leave it.]=],
		},
	},
	chapters = {
		{
			key = "the-champion-of-the-banshee-queen",
			title = "The Champion of the Banshee Queen",
			hint = [=[Answer the Dark Lady's summons and present yourself at the Marris Stead.]=],
			unlock = {
				{ type = "quest", id = 5961 },
			},
			text = [=[The Banshee Queen sends her most seasoned servants east to the {link:the-marris-stead}Marris Stead{/link}. Nathanos greets them with scorn. He assumes they have come to feed his hounds, for he can imagine no other reason for them to trouble him.]=],
		},
		{
			key = "to-kill-with-purpose",
			title = "To Kill With Purpose",
			hint = "Earn your keep at the Marris Stead.",
			unlock = {
				{ type = "quest", id = 6022 },
				{ type = "quest", id = 6042 },
			},
			text = [=[Nathanos's first lessons are errands. His servants grind the rot of freshly slain {link:scourge}Scourge{/link} into feed for his hounds, and they hunt the plaguebats that harass him whenever he leaves the farm. He calls this training. He says, too, that he has better things to do than kill bats, and his servants do not.]=],
		},
		{
			key = "the-ranger-lord-s-behest",
			title = "The Ranger Lord's Behest",
			hint = [=[Recover a record of the Blightcaller's mortal life from the elves of the north.]=],
			unlock = {
				{ type = "quest", id = 6133 },
			},
			text = [=[At {link:quel-lithien-lodge}Quel'Lithien Lodge{/link} the high elves kept a registry of his life as a mortal. Nathanos wanted it back, and he wanted the elves who kept it to suffer. He did not say why. He warned only that no servant of his should be foolish enough to read it.]=],
		},
		{
			key = "ramstein",
			title = "Ramstein",
			hint = "Avenge the Blightcaller's death.",
			unlock = {
				{ type = "quest", id = 6163 },
			},
			text = [=[It was the abomination Ramstein that hovered over Nathanos as he died. After {link:sylvanas-windrunner}Sylvanas{/link} freed him, he hunted it for months until it fled into Stratholme. When its head was brought to him, he wondered aloud whether it had begged, and whether it could even know what mercy was. He swore to hang the head upon his wall.]=],
		},
		{
			key = "the-scarlet-oracle",
			title = "The Scarlet Oracle",
			hint = [=[Carry out the Blightcaller's ruse against the Scarlet Crusade.]=],
			unlock = {
				{ type = "quest", id = 6146 },
				{ type = "quest", id = 6148 },
			},
			text = [=[{link:varimathras}Varimathras{/link} sent word that the Grand Crusader of the {link:scarlet-crusade}Scarlet Crusade{/link} must be struck. Nathanos found the weakness in the Crusade's daily courier. He rewrote the Grand Crusader's orders and sent a servant disguised as a Crusader into {link:tyr-s-hand}Tyr's Hand{/link}. The orders asked that the Scarlet Oracle, {link:demetria}Demetria{/link}, the Grand Crusader's chief counsellor, be sent north to Stratholme. The Crusade obeyed. Nathanos was waiting on the road.]=],
		},
		{
			key = "the-blightcaller-uncovered",
			title = "The Blightcaller Uncovered",
			hint = "Learn who the Blightcaller is, on behalf of Stormwind.",
			unlock = {
				{ type = "quest", id = 6185 },
				{ type = "quest", id = 6186 },
			},
			text = [=[Three agents of {link:si-7}SI:7{/link} went into the {link:eastern-plaguelands}Eastern Plaguelands{/link} to learn who the Blightcaller was, and none came back. Their insignias were found near the {link:the-marris-stead}Marris Stead{/link}. When the truth came out, it broke the hearts of those who had known Nathanos Marris. The regent of {link:stormwind-city}Stormwind{/link} could not believe that the ranger lord had become the champion of {link:sylvanas-windrunner}the Banshee Queen{/link}, and he called for an army to end him.]=],
		},
	},
	mentions = {
