Add({
	kind = "figure",
	id = "lord-maxwell-tyrosus",
	title = "Lord Maxwell Tyrosus",
	aliases = { "Maxwell Tyrosus", "Tyrosus", "Lord Maxwell" },
	subtitle = "Leader of the Argent Dawn",
	tier = "B",
	region = "eastern-plaguelands",
	npc = { 11034 },
	allegiance = "Argent Dawn",
