		{ type = "interact" },
	},
	hint = [=[Seek the lord who keeps council inside the chapel of Light's Hope.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Lord Maxwell Tyrosus leads the {link:argent-dawn}Argent Dawn{/link} from inside the chapel at {link:light-s-hope-chapel}Light's Hope{/link}. He was once of the {link:scarlet-crusade}Scarlet Crusade{/link}. When he saw where its zeal was leading, he refused to follow, and he helped to found an order that would fight the {link:scourge}Scourge{/link} without hating everyone else. He rarely leaves the chapel, and for years he has granted no audience to outsiders. Those who are brought before him have earned it.]=],
		},
		{
			title = "Significance",
			text = [=[Tyrosus is the heart of the Dawn's great experiment: an order that asks no one what race or banner they served, only whether they will stand against the dead. Around him gather an undead knight, a gnomish alchemist, a noble linguist and a grieving son of {link:darrowshire}Darrowshire{/link}. That they work together at all is his doing.]=],
		},
		{
			title = "Deeds",
			text = [=[• He left the {link:scarlet-crusade}Scarlet Crusade{/link} and helped to found the {link:argent-dawn}Argent Dawn{/link}.
• He leads the Dawn in its war against the {link:scourge}Scourge{/link} from {link:light-s-hope-chapel}Light's Hope Chapel{/link}.
• He keeps the Argent Hold, which has stayed locked for years.]=],
		},
		{
			title = "Unrecorded",
			text = [=[The chronicles say little of Tyrosus's life before the Crusade, nor of the lands behind his title. This entry records only his place in the Dawn.]=],
		},
	},
	chapters = {
		{
			key = "an-audience-with-lord-maxwell",
			title = "An Audience with Lord Maxwell",
			hint = [=[Prove yourself a champion of the Dawn, and be brought before its leader.]=],
			unlock = {
				{ type = "quest", id = 5264 },
				{ type = "quest", id = 5265 },
			},
			text = [=[{link:duke-nicholas-zverenhoff}Duke Nicholas Zverenhoff{/link} brought the champion before Lord Maxwell himself, an honor the Dawn had not granted any outsider in years. Tyrosus received the newcomer as a worthy ally. For the first time in many years, the Argent Hold was opened to a hand from outside the order.]=],
		},
	},
	mentions = {
		{
			text = "Lord Maxwell Tyrosus",
			unlock = {
				{ type = "quest", id = 5264 },
			},
		},
		{
			text = "The Argent Hold",
			unlock = {
				{ type = "quest", id = 5265 },
			},
		},
	},
	bonds = {
		{ id = "duke-nicholas-zverenhoff", name = "Duke Nicholas Zverenhoff", note = "brings him champions" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "an undead knight of his order" },
