	hint = [=[Speak with the duke who keeps the Dawn's commissions at Light's Hope.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Duke Nicholas Zverenhoff is one of the most respected leaders of the {link:argent-dawn}Argent Dawn{/link}. He is a noble and a learned man, known across the order as a brilliant linguist. At {link:light-s-hope-chapel}Light's Hope{/link} he gives the Dawn's commission to all who will fight for it, and he pays for every Scourgestone taken from the dead. He is gracious to his allies, and wholly without mercy toward the {link:scourge}Scourge{/link} and the zealots of the {link:scarlet-crusade}Scarlet Crusade{/link}.]=],
		},
		{
			title = "Significance",
			text = [=[The Duke is the Dawn's recruiter and its judge of champions. He believes that anything taken to an extreme is a danger to the world, and he counts the Crusade's blind zeal among those dangers. He teaches that the Dawn must be tolerant and yet unbending in its beliefs. Those he finds worthy he brings before {link:lord-maxwell-tyrosus}Lord Maxwell Tyrosus{/link}.]=],
		},
		{
			title = "Deeds",
			text = [=[• He grants the {link:argent-dawn}Argent Dawn{/link}'s commission, which lets its bearers gather Scourgestones from the fallen.
• He exchanges Scourgestones for the Dawn's tokens of valor.
• He studies strange writings sent to the Dawn, such as the book of a spirit speaker of {link:winterspring}Winterspring{/link}.
• He sends champions into Stratholme against both the Crusade and the {link:scourge}Scourge{/link}.]=],
