			unlock = {
				{ type = "quest", id = 5503 },
				{ type = "quest", id = 6030 },
			},
			text = [=[Every soldier who fights the {link:scourge}Scourge{/link} in the Dawn's name carries its commission. With it, the Duke explained, the bearer may take the Scourgestones that the dead sometimes carry, their marks of rank. The Duke pays for each set, and he pays best of all for the stones of the Scourge's overlords.]=],
