			hint = "Strike at the Scarlet Crusade's records in Stratholme.",
			unlock = {
				{ type = "quest", id = 5251 },
			},
			text = [=[The Duke asked how many innocents the Crusade had destroyed in the name of the Light. He wanted its Archivist in Stratholme slain and the Scarlet Archive burned. When the deed was done, he rejoiced: years of the Crusade's knowledge had gone up in smoke.]=],
		},
