			hint = [=[Bring the Duke proof of what truly commands the Scarlet Crusade.]=],
			unlock = {
				{ type = "quest", id = 5262 },
			},
			text = [=[The head that was laid before the Duke was not a man's. The Grand Crusader of the {link:scarlet-crusade}Scarlet Crusade{/link} was a dreadlord, Balnazzar, brother of the {link:varimathras}Varimathras{/link} who serves in the {link:undercity}Undercity{/link}. Zverenhoff could only wonder how long the Crusade had served a demon without knowing it.]=],
