Add({
	kind = "figure",
	id = "carlin-redpath",
	title = "Carlin Redpath",
	aliases = { "Carlin", "Brother Carlin", "Uncle Carlin" },
	subtitle = "Survivor of Darrowshire",
	tier = "B",
	region = "eastern-plaguelands",
	npc = { 11063 },
	allegiance = "Argent Dawn",
	found = "Light's Hope Chapel",
	pin = { x = 81.5, y = 59.8 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Seek the grieving man of Darrowshire who serves the Dawn at Light's Hope.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Carlin Redpath is a soldier of the {link:argent-dawn}Argent Dawn{/link} at {link:light-s-hope-chapel}Light's Hope Chapel{/link}. He was born in {link:darrowshire}Darrowshire{/link}, and he is one of the very few who lived through the battle that destroyed it. His brother was {link:joseph-redpath}Captain Joseph Redpath{/link}, who led the village's defense. His little niece, {link:pamela-redpath}Pamela{/link}, is dead. Carlin has turned his grief into a single purpose: vengeance on the {link:scourge}Scourge{/link} that took his home.]=],
		},
		{
			title = "Significance",
			text = [=[Carlin is the living memory of {link:darrowshire}Darrowshire{/link}. Its heroes, its villains and its dead cry out to him in his dreams. When the Annals of Darrowshire were brought to him, he learned that he might yet do more for them than grieve.]=],
		},
		{
			title = "Deeds",
			text = [=[• He survived the battle of {link:darrowshire}Darrowshire{/link} and his brother's betrayal.
• He serves the {link:argent-dawn}Argent Dawn{/link} at {link:light-s-hope-chapel}Light's Hope{/link}.
• He gathered the relics of the battle of Darrowshire so that the village's fate might be changed.]=],
		},
	},
	chapters = {
		{
			key = "uncle-carlin",
			title = "Uncle Carlin",
			hint = [=[Bring Carlin word of the little girl who still waits in Darrowshire.]=],
			unlock = {
				{ type = "quest", id = 5241 },
				{ type = "quest", id = 5211 },
			},
			text = [=[Carlin had believed {link:pamela-redpath}Pamela{/link} might be alive. When he learned that she was dead and still waiting as a ghost, he cried out that he would trade places with her in an instant. Then he set his grief aside and asked for the tortured spirits of {link:darrowshire}Darrowshire{/link}'s defenders to be freed from the {link:scourge}Scourge{/link}, for many of them now serve it as ghouls and flayers.]=],
		},
		{
			key = "the-annals-of-darrowshire",
			title = "The Annals of Darrowshire",
			hint = "Bring the Extended Annals of Darrowshire to Light's Hope.",
			unlock = {
				{ type = "quest", id = 5210 },
			},
			text = [=[A strange {link:gnomes}gnome{/link} in {link:ruins-of-andorhal}Andorhal{/link} had worked her magic on the Annals of {link:darrowshire}Darrowshire{/link}, and new pages had appeared at the book's end. They told of the days after the battle, and one of them spoke of Carlin himself. He read them and could not tell whether they were true. He resolved to find out.]=],
		},
		{
			key = "heroes-and-villains",
			title = "Heroes and Villains",
			hint = [=[Gather the relics of the heroes and the villains of Darrowshire.]=],
			unlock = {
				{ type = "quest", id = 5168 },
				{ type = "quest", id = 5181 },
				{ type = "quest", id = 5206 },
			},
			text = [=[The Annals named them all. The libram of the paladin {link:davil-lightfire}Davil Lightfire{/link} had been taken to {link:hearthglen}Hearthglen{/link}. The cracked shield of {link:joseph-redpath}Captain Redpath{/link} lay near a barn in the west. The skull of the ghoul lord {link:horgus-the-ravager}Horgus{/link} lay in a lake, and the broken sword of Marduk the Black in a gorge near {link:corin-s-crossing}Corin's Crossing{/link}. Last came the skulls of {link:scourge}Scourge{/link} champions who had fought in the battle. Carlin did not fully understand why these relics mattered. He only felt that they were bound to his home.]=],
		},
		{
			key = "return-to-chromie",
			title = "Return to Chromie",
			hint = "Send the relics of Darrowshire to the gnome in Andorhal.",
			unlock = {
