	aliases = { "Pamela", "Little Pamela" },
	subtitle = "The Child of Darrowshire",
	tier = "B",
	region = "eastern-plaguelands",
	npc = { 10926 },
	allegiance = "Darrowshire",
	found = "Her family's house, south of the ruins of Darrowshire",
	pin = { x = 36.5, y = 90.8 },
	unlock = {
		{ type = "interact" },
	},
	hint = [=[Seek the little girl who waits in a house south of Darrowshire.]=],
	sections = {
		{
			title = "Summary",
			text = [=[Pamela Redpath is the ghost of a little girl of {link:darrowshire}Darrowshire{/link}. When the {link:scourge}Scourge{/link} came, her father, {link:joseph-redpath}Captain Joseph Redpath{/link}, went to fight, and her aunt {link:marlene-redpath}Marlene{/link} told her to stay in the house and hide. She has been waiting there ever since. She does not know that she is dead. She does not know what became of her father. She knows only that he has not come for her, that bad voices sometimes whisper at her in the dark, and that she left her doll in town.]=],
		},
		{
			title = "Significance",
			text = [=[Pamela is the saddest of the ghosts of the Plaguelands, and the one who has moved the most hearts. Her aunt, her uncle and her sister each asked strangers to find her. Through her, the story of {link:darrowshire}Darrowshire{/link} and of the Redpaths comes back to light.]=],
		},
		{
			title = "Her Family",
			text = [=[Her father was {link:joseph-redpath}Captain Joseph Redpath{/link}, who led the defense of {link:darrowshire}Darrowshire{/link}. Her aunt {link:marlene-redpath}Marlene{/link} hid her when the battle began and now wanders as a spirit near {link:ruins-of-andorhal}Andorhal{/link}. Her uncle {link:carlin-redpath}Carlin{/link} serves the {link:argent-dawn}Argent Dawn{/link} at {link:light-s-hope-chapel}Light's Hope{/link}. Her older sister {link:jessica-redpath}Jessica{/link} fled {link:lordaeron}Lordaeron{/link} before the plague and lives far away in {link:winterspring}Winterspring{/link}. Pamela remembers that Jessica cried when she left, and does not understand why.]=],
		},
