			unlock = {
				{ type = "quest", id = 5142 },
				{ type = "quest", id = 5601 },
			},
			text = [=[Pamela greeted her visitor and asked for a name. She talked of her father, the bravest man in the whole world, and of her sister {link:jessica-redpath}Jessica{/link}, who used to hide with her and jump out to surprise their father when he came home.]=],
