			title = "Pamela's Doll",
			hint = "Find the doll Pamela left in town.",
			unlock = {
				{ type = "quest", id = 5149 },
			},
			text = [=[The doll lay somewhere in the ruins of {link:darrowshire}Darrowshire{/link}, where the dead still walk. When it was found and brought back, Pamela was overjoyed. It was the first thing to comfort her in a very long time.]=],
		},
		{
