			title = "The Battle of Darrowshire",
			hint = [=[Take part in the battle of Darrowshire, and bring a father home.]=],
			unlock = {
				{ type = "quest", id = 5721 },
				{ type = "quest", id = 5942 },
			},
			text = [=[With the {link:gnomes}gnome{/link} {link:chromie}Chromie{/link}'s spell, the battle of {link:darrowshire}Darrowshire{/link} was fought again among its ghosts. This time {link:joseph-redpath}Captain Redpath{/link} was saved. When the fighting ended, Pamela heard her father whisper to her. He told her that he had driven away the ghosts and that he was coming home. She made tea, with a great deal of sugar, for the one who had helped him. Then she gave that friend a key from her father, which opened a chest hidden behind the house.]=],
